const recipesById=new Map(V2_SERVER_RECIPES.map(recipe=>[recipe.id,recipe]));
const piecesById=new Map(V2_SERVER_PIECES.map(piece=>[piece.id,piece]));
export function v2ServerRecipe(id:string){return recipesById.get(id);}
export function v2ServerPiece(id:string){return piecesById.get(id);}
export function v2ServerRecipeAndPiece(recipeId:string){
 const recipe=v2ServerRecipe(recipeId);
 const piece=recipe?v2ServerPiece(recipe.pieceId):undefined;
 return recipe&&piece?{recipe,piece}:undefined;
}
